contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function checkBurn(uint256 v) public {
        require(msg.sender == c.owner());
        require(v <= c.balanceOf(msg.sender));
        uint256 supplyBefore = c.totalSupply();
        c.burn(v);
        assert(c.totalSupply() == supplyBefore - v);
    }
}

