contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function testBurn(uint256 v) public {
        // Caller of this test contract is not the owner of c (owner was set at c's deployment).
        bool reverted = false;
        try c.burn(v) {
            reverted = false;
        } catch {
            reverted = true;
        }
        // Rule: a non-owner's burn attempt must always revert.
        assert(reverted);
    }

    receive() external payable {}
    fallback() external payable {}
}
